mapper.select:
select TEMP.PORTFOLIO_ID portfolioId, PP.PORTFOLIO_NAME portfolioName, TEMP.FINPROD_ID, FP.FINPROD_MARKET_ID finprodMarketId, FP.FINPROD_ABBR finprodAbbr, T4.TYPE_9 secType1, TEMP.AMOUNT amount, NVL(TEMP.AMOUNT, 0) / 100 shareAmt, NVL(TEMP.AMOUNT04, 0) / 100 avaPledgePrin, NVL(t7.amount, 0) / 100 avaShareAmt, MBVI.NETPRICE price, NVL(MBVI.NETPRICE, 0) * NVL(TEMP.AMOUNT, 0)/10000 positionsPrice, atd.COST_POSITION, atd.COST_POSITION_NUM ,tchl.SEC_ACCT_ID ,TEMP.INV_AIM invAim from ( SELECT PSP.PORTFOLIO_ID AS PORTFOLIO_ID , PSP.FINPROD_ID AS FINPROD_ID, PSP.INV_AIM as INV_AIM, SUM(CASE WHEN PSP.HODING_TYPE IN (#{POSITION_TYPE_03}, #{POSITION_TYPE_05}) THEN NVL(PSP.AMOUNT,0) WHEN PSP.HODING_TYPE IN (#{POSITION_TYPE_06}) THEN -1* NVL(PSP.AMOUNT,0) END) AS AMOUNT, SUM(NVL(case when PSP.HODING_TYPE=#{POSITION_TYPE_04} then AMOUNT else 0 end, 0)) AS AMOUNT04 FROM PTL_SEC_POSITION PSP INNER JOIN PTL_PORTFOLIO PP ON PSP.PORTFOLIO_ID = PP.PORTFOLIO_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON PP.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId}
WHERE PSP.BRANCH =0 AND PSP.HODING_TYPE IN (#{POSITION_TYPE_03}, #{POSITION_TYPE_04}, #{POSITION_TYPE_05}, #{POSITION_TYPE_06}) AND PSP.CDATE = to_date(#{sysDate},'yyyy-MM-dd') GROUP BY PSP.PORTFOLIO_ID , PSP.FINPROD_ID, PSP.INV_AIM )TEMP LEFT JOIN PTL_PORTFOLIO PP ON TEMP.PORTFOLIO_ID = PP.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT FP ON TEMP.FINPROD_ID = FP.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T4 ON T4.FINPROD_ID = FP.FINPROD_ID left join ( select portfolio_id, finprod_id, sum(t.amount) as amount from etr_sec_position t where 1=1
AND portfolio_id in
#{item}
and cdate = to_date(#{sysDate},'yyyy-MM-dd') and hoding_type = 'E01' group by portfolio_id,finprod_id ) t7 on t7.portfolio_id = TEMP.portfolio_id and t7.finprod_id = TEMP.finprod_id LEFT JOIN ( select SEC_ID, NETPRICE, LAST_PERIOD from ( select ROW_NUMBER() OVER(PARTITION BY SEC_ID ORDER BY VALUE_DATE DESC) rn, SEC_ID, NETPRICE, LAST_PERIOD from MST_BOND_VALUATION_INFO_TOTAL WHERE VALUE_DATE <= to_date(#{sysDate},'yyyy-MM-dd') ) where rn = 1 ) MBVI ON FP.FINPROD_MARKET_ID = MBVI.SEC_ID left join COST_POSITION_DB atd on atd.portfolio_id = TEMP.portfolio_id and atd.finprod_id = TEMP.finprod_id and atd.CDATE = to_date(#{sysDate},'yyyy-MM-dd') - 1 left join ( select min(esp.SEC_ACCT_ID) SEC_ACCT_ID, esp.FINPROD_ID, esp.PORTFOLIO_ID FROM etr_sec_position esp inner join fin_product fp on fp.FINPROD_ID = esp.SEC_ACCT_ID and fp.FINPROD_TYPE2 = 'F28' where 1=1
AND esp.portfolio_id in
#{item}
and esp.cdate = to_date(#{sysDate},'yyyy-MM-dd') and esp.hoding_type = 'E01' group by esp.FINPROD_ID,esp.PORTFOLIO_ID ) tchl on tchl.portfolio_id = TEMP.portfolio_id and tchl.finprod_id = TEMP.finprod_id where FP.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} /* 交易场所，仅限银行间交易 */ AND FP.TRADE_MARKET in
#{item}
AND TEMP.portfolio_id in
#{item}
AND T4.TYPE_9 = #{secType1,jdbcType=VARCHAR}
AND FP.FINPROD_MARKET_ID in
#{item}

mapper.sql:
select T1.ENTRUST_ID entrustId, decode(T1.ENTRUST_STATUS,'08','流程中','有效') as effectiveStatusName, T1.ENTRUST_STATUS entrustStatus, T8.REAL_NAME invManagerId, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, T1.FINPROD_ID, T3.FINPROD_MARKET_ID finprodMarketId, T3.FINPROD_ABBR finprodAbbr, T4.TYPE_9 secType1, T1.PS, NVL(T1.ENTRUST_NUM,0) / 100 shareNum, T1.PRICE_MODEL priceModel, T1.PRICE unitPrice, T7.FULL_PRICE allPrice, T7.MATURE_YIELD*100 matureYield, T7.EXER_YIELD*100 exerYield, T7.SETTLE_SPREED, T1.VDATE, T1.MDATE, NVL(T5.FINISH_AMT,0)/100 finishAmt, round(NVL(T5.FINISH_AMT,0)*100/(T1.ENTRUST_NUM*100),4)*100 transactioncom, T1.REMARK ,T1.COUNTER_ID counterId ,NVL(T2.PARENT_PORTFOLIO_ID,T2.PORTFOLIO_ID) AS parentPortfolioId ,T1.INV_AIM as invAim ,round(NVL(10,0)*100/(T1.ENTRUST_NUM*100),4)*100 execProcess ,round(NVL(30,0)*100/(T1.ENTRUST_NUM*100),4)*100 transProcess from ETR_ENTRUST T1 INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON T1.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId} INNER JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM( FINISH_AMT) as FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN ETR_ENTRUST_ADD T7 ON T1.ENTRUST_ID = T7.ENTRUST_ID LEFT JOIN SYS_USER T8 ON T1.INV_MANAGER_ID = T8.USER_NAME LEFT JOIN FIN_PRODUCT_TYPE T4 ON T4.FINPROD_ID = T1.FINPROD_ID where T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} and T1.TRADE_MARKET = #{TRADE_MARKET_01}
AND (T1.portfolio_id in
#{item}
OR T2.PARENT_PORTFOLIO_ID in
#{item} )
AND T3.FINPROD_MARKET_ID like '%' || #{finprodAbbr,jdbcType=VARCHAR} || '%'
AND T7.SETTLE_SPREED = #{settleSpeed,jdbcType=VARCHAR}
AND T8.REAL_NAME = #{repManager,jdbcType=VARCHAR}
AND T3.FINPROD_MARKET_ID in
#{item}
AND T1.PS=#{ps}
AND T1.ENTRUST_STATUS = #{entrustStatus}
AND T1.ENTRUST_ID = #{entrustId}
AND T1.ENTRUST_DATE >= to_date(#{entrustStartDate},'yyyy-mm-dd') AND T1.ENTRUST_DATE <= to_date(#{entrustEndDate},'yyyy-mm-dd')
AND T1.PRICE_MODEL = #{priceModel}

select T1.ENTRUST_ID entrustId, decode(T1.ENTRUST_STATUS,'08','流程中','有效') as effectiveStatusName, T1.ENTRUST_STATUS entrustStatus, T8.REAL_NAME invManagerId, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, T1.FINPROD_ID, T3.FINPROD_MARKET_ID finprodMarketId, T3.FINPROD_ABBR finprodAbbr, T4.TYPE_9 secType1, T1.PS, NVL(T1.ENTRUST_NUM,0) / 100 shareNum, T1.PRICE_MODEL priceModel, T1.PRICE unitPrice, T7.FULL_PRICE allPrice, T7.MATURE_YIELD*100 matureYield, T7.EXER_YIELD*100 exerYield, T7.SETTLE_SPREED, T1.VDATE, T1.MDATE, NVL(T5.FINISH_AMT,0)/100 finishAmt, round(NVL(T5.FINISH_AMT,0)*100/(T1.ENTRUST_NUM*100),4)*100 transactioncom, T1.REMARK ,T1.COUNTER_ID counterId ,NVL(T2.PARENT_PORTFOLIO_ID,T2.PORTFOLIO_ID) AS parentPortfolioId ,T1.INV_AIM as invAim ,round(NVL(10,0)*100/(T1.ENTRUST_NUM*100),4)*100 execProcess ,round(NVL(30,0)*100/(T1.ENTRUST_NUM*100),4)*100 transProcess from WFL_ETR_ENTRUST T1 INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON T1.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId}
INNER JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) as FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN WFL_ETR_ENTRUST_ADD T7 ON T1.ENTRUST_ID = T7.ENTRUST_ID LEFT JOIN SYS_USER T8 ON T1.INV_MANAGER_ID = T8.USER_NAME LEFT JOIN FIN_PRODUCT_TYPE T4 ON T4.FINPROD_ID = T1.FINPROD_ID where T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} and T1.TRADE_MARKET = #{TRADE_MARKET_01}
AND T1.portfolio_id in
#{item}
AND T3.FINPROD_ABBR like '%' || #{finprodAbbr,jdbcType=VARCHAR} || '%'
AND T7.SETTLE_SPREED = #{settleSpeed,jdbcType=VARCHAR}
AND T8.REAL_NAME = #{repManager,jdbcType=VARCHAR}
AND T3.FINPROD_MARKET_ID in
#{item}
AND T1.PS=#{ps}
AND T1.ENTRUST_ID = #{entrustId}
AND T1.ENTRUST_DATE >= to_date(#{entrustStartDate},'yyyy-mm-dd') AND T1.ENTRUST_DATE <= to_date(#{entrustEndDate},'yyyy-mm-dd')
AND T1.PRICE_MODEL = #{priceModel}

mapper.select:
select t.finprod_id finprodId,t.share_amt shareAmt,t.yield,t.ps,t.UNIT_CPRICE unitCprice, pt.PORTFOLIO_ID from trd_product_deal t inner JOIN trd_product_deal_add tpda on t.TRADE_ID=tpda.TRADE_ID inner JOIN FIN_PRODUCT T3 ON t.FINPROD_ID = T3.FINPROD_ID inner JOIN fin_product_type fpt on t.finprod_id=fpt.finprod_id and t.branch=fpt.branch inner join ptl_trade pt on pt.BUSI_NO = t.TRADE_ID where 1=1
AND T3.FINPROD_MARKET_ID in
#{item}
AND tpda.PORTFOLIO_ID IN
#{item}
and to_date(#{sysDate},'yyyy-MM-dd')=t.SETTLE_DATE and fpt.type_8='F01' and t.trade_status='01' and t.is_cancel='N' and t.ps in('T01','T02') order by t.UPDATE_TIME asc

select PP.PORTFOLIO_ID AS portfolioId , PP.PORTFOLIO_NAME portfolioName FROM PTL_PORTFOLIO PP INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON PP.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId}
WHERE 1=1
AND PP.PORTFOLIO_ID in
#{item}

select
FP.finprod_id　finprodId,
FP.FINPROD_MARKET_ID finprodMarketId,
FP.FINPROD_ABBR finprodAbbr,
T4.TYPE_9 secType1,
MBVI.NETPRICE price
from
FIN_PRODUCT FP
LEFT JOIN FIN_PRODUCT_TYPE T4 ON T4.FINPROD_ID = FP.FINPROD_ID
LEFT JOIN (
select SEC_ID, NETPRICE, LAST_PERIOD from (
select ROW_NUMBER() OVER(PARTITION BY SEC_ID ORDER BY VALUE_DATE DESC) rn, SEC_ID, NETPRICE, LAST_PERIOD
from MST_BOND_VALUATION_INFO_TOTAL WHERE VALUE_DATE <= to_date(#{sysDate},'yyyy-MM-dd')
) where rn = 1
) MBVI ON FP.FINPROD_MARKET_ID = MBVI.SEC_ID
where
FP.FINPROD_TYPE2 ='F01'
 /* 交易场所，仅限银行间交易 */
    AND FP.TRADE_MARKET in

        #{item}



    AND T4.TYPE_9 = #{secType1,jdbcType=VARCHAR}


    AND FP.finprod_id in

        #{item}

select * from ( SELECT etrptl.PORTFOLIO_ID as portfolioId, e.PORTFOLIO_NAME as portfolioName, etrptl.FINPROD_ID as finprodId, d.FINPROD_NAME as finprodAbbr, d.FINPROD_MARKET_ID as finprodMarketId, c.TYPE_8 as secType1, /*债券一级分类code*/ etrptl.INV_AIM as busiModel, /*业务模式code*/ /*指令汇总可用持仓、指令可质押持仓、指令已质押持仓*/ ROUND(etrptl.ETR_SUM_KYCC,2) as etrPledgePrin, ROUND(etrptl.ETR_PLEDGE_KZYCC,2) as etrAvaPledgePrin, ROUND(etrptl.ETR_PLEDGE_YZYCC,2) as etrAlrPledgePrin, /*交易可用券面总额、交易在途券面总额*/ ROUND(etrptl.PTL_BOND_BFQKYCC,2) as trdAvaShareAmt, ROUND(etrptl.PTL_BOND_BFQZTCC,2) as trdIntransShareAmt, /* 持仓成本 service从map查询 */ null as positionsAmt, /* 持仓单位成本 service从map查询*/ null as unitCost, /* 最新净价 根据规则12来获取*/ null as price, /* 持仓市值 */ ROUND((etrptl.PTL_BOND_BFQKYCC + etrptl.PTL_BOND_BFQZTCC),2) as positionsPrice, /* 浮动盈亏 */ null as floatingPL, /* 账户持仓 */ etrptl.PTL_BOND_ZHCC as accountPosition FROM ( SELECT (CASE WHEN aa.PORTFOLIO_ID IS NULL THEN bb.PORTFOLIO_ID ELSE aa.PORTFOLIO_ID END ) AS PORTFOLIO_ID, (CASE WHEN aa.FINPROD_ID IS NULL THEN bb.FINPROD_ID ELSE aa.FINPROD_ID END ) AS FINPROD_ID, nvl(bb.INV_AIM,aa.INV_AIM) AS INV_AIM, nvl(aa.ETR_SUM_KYCC,0) AS ETR_SUM_KYCC, nvl(aa.ETR_PLEDGE_KZYCC,0) ETR_PLEDGE_KZYCC, nvl(aa.ETR_PLEDGE_YZYCC,0) ETR_PLEDGE_YZYCC, nvl(bb.PTL_BOND_BFQKYCC,0) PTL_BOND_BFQKYCC, nvl(bb.PTL_BOND_BFQZTCC,0) PTL_BOND_BFQZTCC, NVL(bb.PTL_BOND_ZHCC,0) PTL_BOND_ZHCC FROM ( SELECT a.PORTFOLIO_ID, a.FINPROD_ID, a.INV_AIM, sum(CASE WHEN b.S_HOLDINGTYPE='S_001' THEN a.AMOUNT*nvl(b.CAL_FLAG,1) ELSE 0 END) ETR_SUM_KYCC, sum(CASE WHEN b.S_HOLDINGTYPE='S_002' THEN a.AMOUNT*nvl(b.CAL_FLAG,1) ELSE 0 END) ETR_PLEDGE_KZYCC, sum(CASE WHEN a.HODING_TYPE='A_012' THEN a.AMOUNT*nvl(b.CAL_FLAG,1) ELSE 0 END) ETR_PLEDGE_YZYCC FROM ETR_SEC_POSITION_RULE a LEFT JOIN PTL_POSITION_CFG b ON a.HODING_TYPE =b.HOLDINGTYPE AND b.S_HOLDINGTYPE IN ('S_001','S_002') WHERE to_char(a.cdate,'yyyy-MM-dd') = #{cdate,jdbcType=VARCHAR}
AND a.PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
AND a.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
GROUP BY a.PORTFOLIO_ID, a.FINPROD_ID, a.INV_AIM ) aa FULL OUTER JOIN (
select a.PORTFOLIO_ID, a.FINPROD_ID, a.INV_AIM, sum(CASE WHEN a.HODING_TYPE ='A_004' THEN a.AMOUNT ELSE 0 END) AS PTL_BOND_BFQKYCC, sum(CASE WHEN a.HODING_TYPE ='A_008' THEN a.AMOUNT ELSE 0 END) AS PTL_BOND_BFQZTCC, sum(CASE WHEN a.HODING_TYPE ='A_001' THEN a.AMOUNT ELSE 0 END) AS PTL_BOND_ZHCC from PTL_SEC_POSITION_RULE a where to_char(a.cdate,'yyyy-MM-dd') = #{cdate,jdbcType=VARCHAR}
AND a.PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
AND a.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
GROUP BY a.PORTFOLIO_ID, a.FINPROD_ID, a.INV_AIM ) bb ON aa.PORTFOLIO_ID=bb.PORTFOLIO_ID AND aa.FINPROD_ID=bb.FINPROD_ID AND aa.INV_AIM=bb.INV_AIM ) etrptl LEFT JOIN FIN_PRODUCT_TYPE c ON etrptl.FINPROD_ID = c.FINPROD_ID LEFT JOIN FIN_PRODUCT d ON etrptl.FINPROD_ID=d.FINPROD_ID LEFT JOIN PTL_PORTFOLIO e ON etrptl.PORTFOLIO_ID=e.PORTFOLIO_ID where 1=1 AND etrptl.PTL_BOND_ZHCC > 0
and c.TYPE_8 = #{type8}
)
order by ${sort} ${direction}

select
a.PORTFOLIO_ID, a.FINPROD_ID, a.INV_AIM,
sum(nvl(a.BUY_COST_AMT, 0)) BUY_COST_AMT, sum(nvl(a.SHARE_AMT, 0)) SHARE_AMT
from PTL_SEC_VALUTION a
LEFT JOIN FIN_PRODUCT b ON a.FINPROD_ID =b.FINPROD_ID and b.FINPROD_TYPE2 =#{FINPROD_TYPE_TG_F01}
LEFT JOIN FIN_PRODUCT_TYPE c ON a.FINPROD_ID =c.FINPROD_ID
WHERE b.FINPROD_TYPE2 =#{FINPROD_TYPE_TG_F01} AND b.TRADE_MARKET=#{SVR_TRADE_MARKET_01} AND a.CDATE =#{cdate}

    AND a.PORTFOLIO_ID in

        #{item}



    and b.FINPROD_ID = #{finprodId}


    and c.TYPE_8 = #{firstLevelType}

GROUP BY a.PORTFOLIO_ID, a.FINPROD_ID, a.INV_AIM
ORDER BY a.PORTFOLIO_ID, a.FINPROD_ID, a.INV_AIM

select
b.PORTFOLIO_ID ,
a.FINPROD_ID ,
a.INV_AIM ,
a.PS ,
a.UNIT_CPRICE AS PRICE,
a.SHARE_AMT AS AMT
from TRD_PRODUCT_DEAL a
LEFT JOIN TRD_PRODUCT_DEAL_ADD b ON a.TRADE_ID =b.TRADE_ID
LEFT JOIN FIN_PRODUCT c ON a.FINPROD_ID =c.FINPROD_ID AND c.FINPROD_TYPE2 =#{FINPROD_TYPE_TG_F01}
LEFT JOIN FIN_PRODUCT_TYPE d ON d.FINPROD_ID =a.FINPROD_ID
WHERE a.TRADE_DATE =#{cdate} AND c.FINPROD_TYPE2 =#{FINPROD_TYPE_TG_F01} AND c.TRADE_MARKET=#{SVR_TRADE_MARKET_01}
AND a.PS IN (#{PS_T01},#{PS_T02},#{PS_T03}) AND a.TRADE_STATUS =#{TRADE_STATUS_01}
AND a.IS_CANCEL=#{YN_N}

    AND b.PORTFOLIO_ID in

        #{item}



    and a.FINPROD_ID = #{finprodId}


    and d.TYPE_8 = #{firstLevelType}

ORDER BY b.PORTFOLIO_ID, a.FINPROD_ID , a.INV_AIM , a.CREATE_TIME DESC

SELECT ROUND(sum(nvl(summary.t0kyxj,0)),2) AS T0KYXJ, /*T日可用现金*/ ROUND(sum(nvl(summary.t1kyxj,0)),2) AS T1KYXJ, /*T+1日可用现金*/ ROUND(sum(nvl(summary.AMOUNT,0)),2) AS ZHXJ, /*账户现金*/ ROUND(sum(nvl(summary.rrqmkdgh,0)),2) AS RRQMKDGHCC, /*融入券卖空待购回持仓*/ ROUND(sum(nvl(summary.zctrkycc,0)),2) AS ZCTRKYCC, /*资产T日可用持仓*/ ROUND(sum(nvl(summary.zct1rkycc,0)),2) AS ZCT1RKYCC, /*资产T+1日可用持仓*/ ROUND(sum(nvl(summary.bfqtrkycc,0)),2) AS BFQTRKYCC, /*本方券T日可用持仓*/ ROUND(sum(nvl(summary.bfqt1rkycc,0)),2) AS BFQT1RKYCC, /*本方券T+1日可用持仓*/ ROUND(sum(nvl(summary.rrqtrkycc,0)),2) AS RRQTRKYCC, /*融入券T日可用持仓*/ ROUND(sum(nvl(summary.rrqt1rkycc,0)),2) AS RRQT1RKYCC /*融入券T+1日可用持仓*/ FROM ( /*多组合，再汇总一遍*/ SELECT aa.t0kyxj, aa.t1kyxj, cc.AMOUNT, bb.rrqmkdgh, bb.zctrkycc, bb.zct1rkycc, bb.bfqtrkycc, bb.bfqt1rkycc, bb.rrqtrkycc, bb.rrqt1rkycc FROM( select a.PORTFOLIO_ID, sum( CASE WHEN b.S_HOLDINGTYPE='S_004' AND a.DATE_TYPE ='0' THEN a.AMOUNT*nvl(b.CAL_FLAG,1) ELSE 0 END ) AS t0kyxj, /*T日可用现金*/ sum( CASE WHEN b.S_HOLDINGTYPE='S_004' AND a.DATE_TYPE ='1' THEN a.AMOUNT*nvl(b.CAL_FLAG,1) ELSE 0 END ) AS t1kyxj /*T+1日可用现金*/ from ETR_CASH_POSITION_RULE a LEFT JOIN PTL_POSITION_CFG b ON a.HODING_TYPE =b.HOLDINGTYPE AND b.S_HOLDINGTYPE IN ('S_004') where to_char(a.cdate,'yyyy-MM-dd') = #{cdate}
AND a.PORTFOLIO_ID in
#{item}
GROUP BY a.PORTFOLIO_ID ) aa FULL OUTER JOIN ( select a.PORTFOLIO_ID, sum( CASE WHEN b.S_HOLDINGTYPE='S_003' THEN a.AMOUNT*nvl(b.CAL_FLAG,1) ELSE 0 END ) AS rrqmkdgh, /*融入券卖空待购回持仓*/ sum( CASE WHEN b.S_HOLDINGTYPE='S_001' AND a.DATE_TYPE ='0' THEN a.AMOUNT*nvl(b.CAL_FLAG,1) ELSE 0 END ) AS zctrkycc, /*资产T日可用持仓*/ sum( CASE WHEN b.S_HOLDINGTYPE='S_001' AND a.DATE_TYPE ='1' THEN a.AMOUNT*nvl(b.CAL_FLAG,1) ELSE 0 END ) AS zct1rkycc, /*资产T+1日可用持仓*/ sum(CASE WHEN a.HODING_TYPE='A_004' AND a.DATE_TYPE ='0' THEN AMOUNT ELSE 0 END) AS bfqtrkycc, /*本方券T日可用持仓*/ sum(CASE WHEN a.HODING_TYPE='A_004' AND a.DATE_TYPE ='1' THEN AMOUNT ELSE 0 END) AS bfqt1rkycc, /*本方券T+1日可用持仓*/ sum(CASE WHEN a.HODING_TYPE='A_005' AND a.DATE_TYPE ='0' THEN AMOUNT ELSE 0 END) AS rrqtrkycc, /*融入券T日可用持仓*/ sum(CASE WHEN a.HODING_TYPE='A_005' AND a.DATE_TYPE ='1' THEN AMOUNT ELSE 0 END) AS rrqt1rkycc /*融入券T+1日可用持仓*/ from ETR_SEC_POSITION_RULE a LEFT JOIN PTL_POSITION_CFG b ON a.HODING_TYPE =b.HOLDINGTYPE AND b.S_HOLDINGTYPE IN ('S_001','S_003') where to_char(a.cdate,'yyyy-MM-dd') = #{cdate}
and a.FINPROD_ID = #{finprodId}
AND a.PORTFOLIO_ID in
#{item}
GROUP BY a.PORTFOLIO_ID ) bb ON aa.PORTFOLIO_ID=bb.PORTFOLIO_ID LEFT JOIN (
SELECT d.PORTFOLIO_ID, sum(d.AMOUNT) AMOUNT FROM PTL_CASH_POSITION_RULE d where to_char(d.cdate,'yyyy-MM-dd') = #{cdate} AND d.HODING_TYPE ='C_01'
and d.ACCT_ID = #{acctId}
AND d.PORTFOLIO_ID in
#{item}
GROUP BY d.PORTFOLIO_ID ) cc ON nvl(aa.PORTFOLIO_ID, bb.PORTFOLIO_ID)=cc.PORTFOLIO_ID ) summary

SELECT t1.FINPROD_ID secId, t1.FINPROD_MARKET_ID marketId, t1.FINPROD_NAME secName, t1.FINPROD_ABBR secAbbr, sdl.ITEM_VALUE secType, t1.ISSUER issuer, TO_CHAR(t1.VDATE,'yyyy-MM-dd') vdate, TO_CHAR(t1.MDATE,'yyyy-MM-dd') mdate, MBVI.LAST_PERIOD lastqx, MBVI.VALUE_SOURCE valueSource, MBVI.VALUE_DATE valueDate, TO_CHAR(t4.PAY_DATE,'yyyy-MM-dd') lastPaydate, sd.ITEM_VALUE rateType, t6.RATE*100 rate, MBCR.O_TYPE otype, sd1.ITEM_VALUE zxGrade, sd1.ITEM_VALUE ztGrade, t1.IS_RIGHT xqFlg, TO_CHAR(A.EXERCISE_DATE,'yyyy-MM-dd') xqdate, MBVI.NETVALUATION_EXERCISE priceXq, MBVI.NETPRICE priceTj, t2.TYPE_7, t1.ISSUE_TYPE, t1.SPONSOR sponsorName FROM FIN_PRODUCT t1 LEFT JOIN FIN_PRODUCT_TYPE t2 ON t1.FINPROD_ID = t2.FINPROD_ID LEFT JOIN MST_BOND_VALUATION_INFO MBVI ON t1.FINPROD_MARKET_ID = MBVI.SEC_ID LEFT JOIN ( select f2.FINPROD_ID, min(f1.PAY_DATE) PAY_DATE from fin_cash_plan f1 inner join fin_cash_info f2 on f1.CASH_ID = f2.CASH_ID inner join FIN_PRODUCT f3 on f2.FINPROD_ID = f3.FINPROD_ID where f2.CASH_TYPE_2 = 'C02' and f3.FINPROD_TYPE2 = 'F01' group by f2.FINPROD_ID ) t4 on t4.FINPROD_ID = t1.FINPROD_ID left join fin_cash_info t5 on t5.FINPROD_ID = t1.FINPROD_ID AND t5.CASH_TYPE_2 = 'C02' and t5.FINPROD_TYPE = '01' LEFT JOIN FIN_RATE_INFO t6 ON t6.CASH_ID = t5.CASH_ID LEFT JOIN mst_customer_info t7 ON t1.SPONSOR = t7.CUSTOMER_ID LEFT JOIN (
select A.FINPROD_ID,min(A.EXERCISE_DATE) EXERCISE_DATE from FIN_EXERCISE_PLAN A where 1 = 1
AND A.FINPROD_ID = #{secId}
group by A.FINPROD_ID ) B on t1.FINPROD_ID = B.FINPROD_ID LEFT JOIN MST_BOND_CREDIT_RATING MBCR ON t1.FINPROD_MARKET_ID = MBCR.O_CODE LEFT JOIN SYS_DATADICT_LIST sdl ON sdl.ITEM_CODE = t2.TYPE_2 LEFT JOIN SYS_DATADICT_LIST sd ON sd.DICT_CODE = 'INT_TYPE' AND sd.ITEM_CODE = t6.INT_TYPE LEFT JOIN SYS_DATADICT_LIST sd1 ON sd1.DICT_CODE = 'MAIN_GRADE_RESULT' AND sd1.ITEM_CODE = MBCR.GRADE_RESULT LEFT JOIN FIN_EXERCISE_PLAN A ON t1.FINPROD_ID = A.FINPROD_ID where 1=1 AND t1.FINPROD_TYPE2='F01'
AND t1.FINPROD_ID = #{secId}
